,"isNew":false},{"id":"matecznik-original","storageId":"centro:drinks:napoje-gorace:matecznik:matecznik-original","name":"Herbata Białowieska Oryginalna","price":"16","portion":"","description":["Relaksująca kompozycja owoców, ziół i kwiatów oparta na starodawnej recepturze z czasów Unii Polsko-Litewskiej."],"recommended":false,"spicy":false,"meatless":false,"isNew":false},{"id":"matecznik-winter","storageId":"centro:drinks:napoje-gorace:matecznik:matecznik-winter","name":"Herbata Zimowa Białowieska","price":"18/23","portion":"","description":["Zimowy napar z owoców tradycyjnych i liofilizowanych w dwóch wariantach: z syropem z pigwowca i sokiem z imbiru lub z pigwowcem i podlaską nalewką (+5 zł)."],"recommended":false,"spicy":false,"meatless":false,"isNew":false}]}]}]}]}$menu_manifest$::jsonb;
  section jsonb;
  cat jsonb;
  grp jsonb;
  dish jsonb;
  old_category record;
  old_group record;
  menu_id text;
  archive_id constant text := 'centro:archive-menu-2026-11';
  archive_category_id text;
  archive_group_id text;
  category_order integer;
  group_order integer;
  item_order integer;
  old_count integer;
  imported_count integer := 0;
  linked_photo_count integer;
BEGIN
  PERFORM id FROM public.restaurants WHERE id = 'centro' FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  PERFORM id FROM public.menus WHERE restaurant_id = 'centro' ORDER BY id FOR UPDATE;
  IF (SELECT count(*) FROM public.menus WHERE restaurant_id = 'centro' AND key IN ('main','kids','drinks')) <> 3 THEN
    RAISE EXCEPTION 'Centro must have three fixed sections before menu import';
  END IF;
  SELECT count(*), count(i.image_id) INTO old_count, linked_photo_count FROM public.menu_items i
    JOIN public.menu_groups g ON g.id=i.group_id JOIN public.menu_categories c ON c.id=g.category_id
    JOIN public.menus m ON m.id=c.menu_id WHERE m.restaurant_id='centro';
  INSERT INTO public.menus (id,restaurant_id,key,title,sort_order)
    VALUES (archive_id,'centro','archive-menu-2026-11','Archiwum menu — 2026-11',100);

  -- Clone containers before reusing original category/group identities. Unmatched items remain
  -- in the hidden archive even if their original group is reactivated for the new menu.
  FOR old_category IN SELECT c.* FROM public.menu_categories c JOIN public.menus m ON m.id=c.menu_id
    WHERE m.restaurant_id='centro' AND m.key IN ('main','kids','drinks') ORDER BY c.id
  LOOP
    archive_category_id := archive_id || ':category:' || md5(old_category.id);
    INSERT INTO public.menu_categories (id,menu_id,slug,label,note,columns,column_break,sort_order)
      VALUES (archive_category_id,archive_id,old_category.slug,old_category.label,old_category.note,
        old_category.columns,old_category.column_break,old_category.sort_order);
    FOR old_group IN SELECT * FROM public.menu_groups WHERE category_id=old_category.id ORDER BY id LOOP
      archive_group_id := archive_id || ':group:' || md5(old_group.id);
      INSERT INTO public.menu_groups (id,category_id,title,note,after_note,sort_order)
        VALUES (archive_group_id,archive_category_id,old_group.title,old_group.note,old_group.after_note,old_group.sort_order);
      UPDATE public.menu_items SET group_id=archive_group_id WHERE group_id=old_group.id;
      UPDATE public.menu_groups SET category_id=archive_category_id WHERE id=old_group.id;
    END LOOP;
    UPDATE public.menu_categories SET menu_id=archive_id WHERE id=old_category.id;
  END LOOP;

  FOR section IN SELECT value FROM jsonb_array_elements(payload->'sections') LOOP
    SELECT id INTO STRICT menu_id FROM public.menus WHERE restaurant_id='centro' AND key=section->>'key';
    category_order := 0;
    FOR cat IN SELECT value FROM jsonb_array_elements(section->'categories') LOOP
      IF EXISTS (SELECT 1 FROM public.menu_categories c JOIN public.menus m ON m.id=c.menu_id
        WHERE c.id=cat->>'storageId' AND m.restaurant_id<>'centro') THEN
        RAISE EXCEPTION 'Import category identity belongs to another restaurant';
      END IF;
      INSERT INTO public.menu_categories (id,menu_id,slug,label,note,columns,column_break,sort_order)
        VALUES (cat->>'storageId',menu_id,cat->>'id',cat->>'label',coalesce(cat->>'note',''),coalesce((cat->>'columns')::integer,1),coalesce((cat->>'columnBreak')::integer,1),category_order)
        ON CONFLICT (id) DO UPDATE SET menu_id=excluded.menu_id,slug=excluded.slug,label=excluded.label,
          note=excluded.note,columns=excluded.columns,column_break=excluded.column_break,sort_order=excluded.sort_order;
      group_order := 0;
      FOR grp IN SELECT value FROM jsonb_array_elements(cat->'groups') LOOP
        IF EXISTS (SELECT 1 FROM public.menu_groups g JOIN public.menu_categories c ON c.id=g.category_id
          JOIN public.menus m ON m.id=c.menu_id WHERE g.id=grp->>'storageId' AND m.restaurant_id<>'centro') THEN
          RAISE EXCEPTION 'Import group identity belongs to another restaurant';
        END IF;
        INSERT INTO public.menu_groups (id,category_id,title,note,after_note,sort_order)
          VALUES (grp->>'storageId',cat->>'storageId',coalesce(grp->>'title',''),coalesce(grp->>'note',''),coalesce(grp->>'afterNote',''),group_order)
          ON CONFLICT (id) DO UPDATE SET category_id=excluded.category_id,title=excluded.title,
            note=excluded.note,after_note=excluded.after_note,sort_order=excluded.sort_order;
        item_order := 0;
        FOR dish IN SELECT value FROM jsonb_array_elements(grp->'items') LOOP
          IF EXISTS (SELECT 1 FROM public.menu_items i JOIN public.menu_groups g ON g.id=i.group_id
            JOIN public.menu_categories c ON c.id=g.category_id JOIN public.menus m ON m.id=c.menu_id
            WHERE i.id=dish->>'storageId' AND m.restaurant_id<>'centro') THEN
            RAISE EXCEPTION 'Import dish identity belongs to another restaurant';
          END IF;
          INSERT INTO public.menu_items (id,group_id,name,portion,price,description,meatless,recommended,spicy,is_new,visible,sort_order)
            VALUES (dish->>'storageId',grp->>'storageId',dish->>'name',dish->>'portion',dish->>'price',
              ARRAY(SELECT jsonb_array_elements_text(dish->'description')),
              (dish->>'meatless')::boolean,(dish->>'recommended')::boolean,(dish->>'spicy')::boolean,false,true,item_order)
            ON CONFLICT (id) DO UPDATE SET group_id=excluded.group_id,name=excluded.name,portion=excluded.portion,
              price=excluded.price,description=excluded.description,meatless=excluded.meatless,recommended=excluded.recommended,
              spicy=excluded.spicy,is_new=false,visible=true,sort_order=excluded.sort_order;
          -- allergens deliberately omitted from the conflict update: retain explicit existing values.
          imported_count := imported_count+1;
          item_order := item_order+1;
        END LOOP;
        group_order := group_order+1;
      END LOOP;
      category_order := category_order+1;
    END LOOP;
  END LOOP;
  UPDATE public.menu_items i SET image_id=NULL,image_alt='' FROM public.menu_groups g,public.menu_categories c,public.menus m
    WHERE i.group_id=g.id AND g.category_id=c.id AND c.menu_id=m.id AND m.restaurant_id='centro';
  UPDATE public.menus SET version=version+1,updated_at=now()
    WHERE restaurant_id='centro' AND key IN ('main','kids','drinks');
  IF imported_count <> 115 OR (SELECT count(*) FROM public.menu_items i JOIN public.menu_groups g ON g.id=i.group_id
    JOIN public.menu_categories c ON c.id=g.category_id JOIN public.menus m ON m.id=c.menu_id
    WHERE m.restaurant_id='centro' AND m.key IN ('main','kids','drinks')) <> imported_count THEN
    RAISE EXCEPTION 'Unexpected Centro import count';
  END IF;
  INSERT INTO public.audit_log (actor_id,action,target_id,details)
    VALUES ('migration:0007','menu.screenshot-import','centro',jsonb_build_object('revision',payload->>'revision',
      'previousItems',old_count,'importedItems',imported_count,'detachedDishPhotos',linked_photo_count));
END $import$;
